<section class="form-card wide"><h2>Book Appointment</h2><form method="post" action="<?=htmlspecialchars($config['base_url'])?>/appointments/book"><div class="grid2"><label>Doctor<select name="doctor_id" required><option value="">Select</option><?php foreach($doctors as $d):?><option value="<?=$d['id']?>">Dr. <?=htmlspecialchars($d['name'])?></option><?php endforeach?></select></label><label>Hospital ID<input name="hospital_id" type="number"></label><label>Date<input name="date" type="date" required></label><label>Start Time<input name="start_time" type="time" required></label><label>End Time<input name="end_time" type="time" required></label><label>Consultation<select name="type"><option>hospital</option><option>video</option><option>emergency</option></select></label><label>Fee<input name="fee" type="number" step="0.01"></label><label>Reason<input name="reason"></label></div><button class="btn primary">Confirm Appointment</button></form></section>